script:
frappe.ui.form.on('Gym Member', {
    refresh: function(frm) {
        if (frm.is_new()) return;
        frm.add_custom_button(__('Manage Membership'), function() {
            open_manage_dialog(frm);
        });
    }
});

function open_manage_dialog(frm) {
    frappe.call({
        method: 'gym_management.gym_erp_system.api.get_member_subscriptions',
        args: { member: frm.doc.name },
        callback: function(r) {
            let subs = (r.message || []).filter(s => ['Active', 'Scheduled', 'Frozen', 'Cancelled'].includes(s.status));
            if (!subs.length) {
                frappe.msgprint(__('This member has no memberships to manage.'));
                return;
            }

            let checklist_html = subs.map(s => `
                <div class="checkbox">
                    <label>
                        <input type="checkbox" class="sub-check" data-sub="${s.name}" data-status="${s.status}" data-plan="${s.gym_plan}">
                        ${s.gym_plan_name || s.gym_plan} — <b>${s.status}</b> (${frappe.datetime.str_to_user(s.start_date)} &rarr; ${frappe.datetime.str_to_user(s.end_date)})
                    </label>
                </div>
            `).join('');

            let dialog = new frappe.ui.Dialog({
                title: __('Manage Membership'),
                fields: [
                    { fieldname: 'action', fieldtype: 'Select', label: __('Action'), options: ['Freeze', 'Cancel', 'Resume', 'Change Plan'], reqd: 1, default: 'Freeze' },
                    { fieldname: 'freeze_days', fieldtype: 'Int', label: __('Freeze Days'), depends_on: 'eval:doc.action=="Freeze"' },
                    { fieldname: 'reason', fieldtype: 'Small Text', label: __('Cancellation Reason'), depends_on: 'eval:doc.action=="Cancel"' },
                    { fieldname: 'change_plan_note', fieldtype: 'HTML', options: `<p class="text-muted">${__('Select exactly one Active membership below, then Continue.')}</p>`, depends_on: 'eval:doc.action=="Change Plan"' },
                    { fieldname: 'select_all', fieldtype: 'Check', label: __('Select All') },
                    { fieldname: 'subs_html', fieldtype: 'HTML', options: `<div class="sub-checklist">${checklist_html}</div>` }
                ],
                primary_action_label: __('Continue'),
                primary_action: function(values) {
                    let checked = dialog.$wrapper.find('.sub-check:checked').map(function() {
                        return { name: $(this).data('sub'), status: $(this).data('status'), gym_plan: $(this).data('plan') };
                    }).get();

                    if (!checked.length) {
                        frappe.msgprint(__('Select at least one membership.'));
                        return;
                    }

                    if (values.action === 'Change Plan') {
                        if (checked.length !== 1) {
                            frappe.msgprint(__('Change Plan ek waqt mein sirf ek membership ke liye ho sakta hai — sirf ek select karein.'));
                            return;
                        }
                        if (checked[0].status !== 'Active') {
                            frappe.msgprint(__('Plan change sirf Active membership par ho sakta hai.'));
                            return;
                        }
                        dialog.hide();
                        open_change_plan_flow(checked[0].name, checked[0].gym_plan, function() {
                            frm.reload_doc();
                        });
                        return;
                    }

                    apply_bulk_action(frm, dialog, values, checked);
                }
            });

            dialog.show();

            dialog.fields_dict.select_all.$input.on('change', function() {
                let checked = $(this).is(':checked');
                dialog.$wrapper.find('.sub-check').prop('checked', checked);
            });
        }
    });
}

async function apply_bulk_action(frm, dialog, values, checked) {
    let skipped = 0;
    let eligible = [];

    checked.forEach(function(sub) {
        if (values.action === 'Freeze') {
            if ((sub.status !== 'Active' && sub.status !== 'Scheduled') || !values.freeze_days || values.freeze_days <= 0) { skipped++; return; }
            eligible.push({ method: 'gym_management.gym_erp_system.gym_subscription.freeze_subscription', args: { subscription: sub.name, freeze_days: values.freeze_days } });
        } else if (values.action === 'Cancel') {
            if (sub.status === 'Cancelled' || sub.status === 'Expired') { skipped++; return; }
            eligible.push({ method: 'gym_management.gym_erp_system.gym_subscription.cancel_subscription', args: { subscription: sub.name, reason: values.reason } });
        } else if (values.action === 'Resume') {
            if (sub.status !== 'Frozen') { skipped++; return; }
            eligible.push({ method: 'gym_management.gym_erp_system.gym_subscription.resume_subscription', args: { subscription: sub.name } });
        }
    });

    if (!eligible.length) {
        frappe.msgprint(__('None of the selected memberships were eligible for that action (Resume only works on Frozen, Freeze/Cancel only work on Active/Scheduled).'));
        return;
    }

    frappe.dom.freeze(__('Processing...'));
    let failed = 0;
    // IMPORTANT: process one at a time (not in parallel) — multiple subscriptions
    // belonging to the same member all update that member's status, so running
    // them concurrently can deadlock the database.
    for (const call of eligible) {
        try {
            await frappe.call(call);
        } catch (e) {
            failed++;
        }
    }
    frappe.dom.unfreeze();

    let msg = __('Done.');
    if (skipped || failed) {
        msg = __('Done — {0} skipped, {1} failed.', [skipped, failed]);
    }
    frappe.show_alert({ message: msg, indicator: failed ? 'orange' : 'green' });
    dialog.hide();
    frm.reload_doc();
}

function open_change_plan_flow(subscription_name, current_plan, on_done) {
    let plan_dialog = new frappe.ui.Dialog({
        title: __('Change Plan'),
        fields: [
            {
                fieldname: 'new_plan',
                fieldtype: 'Link',
                options: 'Gym Plan',
                label: __('New Plan'),
                reqd: 1,
                get_query: function() {
                    return {
                        filters: {
                            name: ['!=', current_plan],
                            disabled: 0,
                            one_time_charge: 0
                        }
                    };
                }
            },
            {
                fieldname: 'mode',
                fieldtype: 'Select',
                label: __('Activate New Plan For'),
                options: [
                    { label: __('Remaining Days Only (same end date as current plan)'), value: 'remaining' },
                    { label: __('Full New Tenure (fresh full cycle from today)'), value: 'full' }
                ],
                reqd: 1,
                default: 'remaining'
            }
        ],
        primary_action_label: __('Calculate'),
        primary_action: function(values) {
            frappe.call({
                method: 'gym_management.gym_erp_system.gym_subscription.preview_change_plan',
                args: { subscription: subscription_name, new_plan: values.new_plan },
                freeze: true,
                callback: function(r) {
                    if (!r.message) return;
                    plan_dialog.hide();
                    show_change_plan_confirmation(subscription_name, values.new_plan, values.mode, r.message, on_done);
                }
            });
        }
    });
    plan_dialog.show();
}

function show_change_plan_confirmation(subscription_name, new_plan, mode, calc, on_done) {
    let chosen = calc.modes[mode];
    if (!chosen || !chosen.available) {
        frappe.msgprint(__("Is mode mein switch nahi ho sakta (remaining days 0 hain). Dusra mode try karein."));
        return;
    }
    let net = chosen.net_amount;
    let net_html;
    if (net > 0) {
        net_html = '<p style="font-size:16px;"><b>' + __('Customer has to pay') + ': Rs ' + frappe.format(net, { fieldtype: 'Currency' }) + '</b></p>';
    } else if (net < 0) {
        net_html = '<p style="font-size:16px;"><b>' + __('You have to refund the customer') + ': Rs ' + frappe.format(Math.abs(net), { fieldtype: 'Currency' }) + '</b></p>';
    } else {
        net_html = '<p style="font-size:16px;"><b>' + __('No payment or refund needed') + ' (' + __('exact match') + ')</b></p>';
    }

    let summary_html = '<div>' +
        '<p><b>' + __('Current Plan') + ':</b> ' + calc.old_plan_label + ' &mdash; ' + __('remaining') + ' ' + calc.remaining_days + ' ' + __('day(s)') + ', ' + __('unused value') + ': Rs ' + frappe.format(calc.old_credit, { fieldtype: 'Currency' }) + '</p>' +
        '<p><b>' + __('New Plan') + ':</b> ' + calc.new_plan_label + ' &mdash; ' + __('cost for this change') + ': Rs ' + frappe.format(chosen.new_cost, { fieldtype: 'Currency' }) + ', ' + __('active until') + ' ' + frappe.datetime.str_to_user(chosen.new_end_date) + '</p>' +
        '<hr>' + net_html + '</div>';

    let confirm_dialog = new frappe.ui.Dialog({
        title: __('Confirm Plan Change'),
        fields: [{ fieldname: 'summary', fieldtype: 'HTML', options: summary_html }],
        primary_action_label: __('Confirm & Generate Bill'),
        primary_action: function() {
            frappe.call({
                method: 'gym_management.gym_erp_system.gym_subscription.execute_change_plan',
                args: { subscription: subscription_name, new_plan: new_plan, mode: mode },
                freeze: true,
                freeze_message: __('Processing plan change...'),
                callback: function(r) {
                    confirm_dialog.hide();
                    if (!r.message) return;
                    frappe.msgprint({
                        title: __('Plan Changed'),
                        message: __('New invoice {0} created.', [r.message.new_invoice]) +
                            (r.message.credit_note ? ' ' + __('Credit note {0} created.', [r.message.credit_note]) : ''),
                        indicator: 'green'
                    });
                    if (on_done) on_done();
                }
            });
        }
    });
    confirm_dialog.show();
}

function recalc(frm) {
    let mode = frm.doc.pricing_mode;
    let rows = frm.doc.items || [];

    if (mode === 'Manual Per-Service Price') {
        let total = rows.reduce((sum, r) => sum + flt(r.price), 0);
        frm.set_value('overall_price', total);
    } else if (rows.length) {
        let overall = flt(frm.doc.overall_price);
        if (mode === 'One Total Price - Equal Split') {
            let each = overall / rows.length;
            rows.forEach(r => { r.price = each; });
        } else if (mode === 'One Total Price - Proportional Split') {
            let total_weight = rows.reduce((sum, r) => sum + flt(r.plan_price), 0) || 1;
            rows.forEach(r => {
                let weight = flt(r.plan_price) / total_weight;
                r.price = overall * weight;
            });
        }
        frm.refresh_field('items');
    }
}

frappe.ui.form.on('Gym Package', {
    pricing_mode: function(frm) {
        recalc(frm);
    },
    overall_price: function(frm) {
        recalc(frm);
    },
    items_add: function(frm) {
        recalc(frm);
    },
    items_remove: function(frm) {
        recalc(frm);
    }
});

frappe.ui.form.on('Gym Package Item', {
    gym_plan: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.gym_plan) return;
        frappe.db.get_value('Gym Plan', row.gym_plan, 'monthly_fee', (r) => {
            row.plan_price = r.monthly_fee || 0;
            if (frm.doc.pricing_mode === 'Manual Per-Service Price') {
                row.price = row.plan_price;
            }
            frm.refresh_field('items');
            recalc(frm);
        });
    },
    price: function(frm) {
        recalc(frm);
    }
});
